package dev.frostlake.functions;

import dev.frostlake.BaseDatabaseTest;
import dev.frostlake.storage.Row;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.assertEquals;

/**
 * SUM and AVG over FLOATs in a ROWS frame that moves along its partition read the frame's running sum, which
 * rows enter and leave, rather than a sum taken afresh: a frame that ends FOLLOWING the current row is walked
 * from the partition's end, SUM adds with Kahan compensation and AVG plainly. A whole partition under an
 * ORDER BY is summed in the rows' input order. Every digit is Snowflake's, read through a twentieth-decimal
 * cast.
 */
public class WindowFloatFrameSumTest extends BaseDatabaseTest {

    private static final String FOUR = "(SELECT 1 AS i, 1 AS k, 0.3::FLOAT AS x UNION ALL SELECT 2, 1, 0.7::FLOAT UNION ALL SELECT 3, 1, 0.1::FLOAT UNION ALL SELECT 4, 1, 0.5::FLOAT)";
    private static final String SIX = "(SELECT 1 AS i, 1 AS k, 0.3::FLOAT AS x UNION ALL SELECT 2, 1, 0.7::FLOAT UNION ALL SELECT 3, 1, 0.1::FLOAT UNION ALL SELECT 4, 1, 0.5::FLOAT UNION ALL SELECT 5, 1, 0.9::FLOAT UNION ALL SELECT 6, 1, 0.2::FLOAT)";
    private static final String WITH_NULLS = "(SELECT 1 AS i, 1 AS k, 0.3::FLOAT AS x UNION ALL SELECT 2, 1, NULL::FLOAT UNION ALL SELECT 3, 1, 0.7::FLOAT UNION ALL SELECT 4, 1, 0.1::FLOAT UNION ALL SELECT 5, 1, NULL::FLOAT UNION ALL SELECT 6, 1, 0.5::FLOAT)";
    private static final String SCRAMBLED = "(SELECT 3 AS i, 1 AS k, 0.1::FLOAT AS x UNION ALL SELECT 1, 1, 0.3::FLOAT UNION ALL SELECT 4, 1, 0.5::FLOAT UNION ALL SELECT 2, 1, 0.7::FLOAT)";
    private static final String PARTITIONED = "(SELECT 1 AS i, 1 AS k, 0.3::FLOAT AS x UNION ALL SELECT 2, 1, NULL UNION ALL SELECT 3, 1, 0.7::FLOAT UNION ALL SELECT 4, 1, 0.1::FLOAT UNION ALL SELECT 5, 2, 0.5::FLOAT UNION ALL SELECT 6, 1, NULL UNION ALL SELECT 7, 2, 0.9::FLOAT)";
    private static final String TENTHS = "(SELECT SEQ4() AS i, 0.1::FLOAT AS x FROM TABLE(GENERATOR(ROWCOUNT => 12)))";

    /** Every row's cells, a comma between cells and a bar between rows. */
    private String rows(final String sql) {
        final StringBuilder out = new StringBuilder();
        for (final Row row : engine.executeQuery(sql).getRows()) {
            if (out.length() > 0) {
                out.append(" | ");
            }
            for (int i = 0; i < row.getValues().size(); i++) {
                if (i > 0) {
                    out.append(", ");
                }
                out.append(row.getValue(i));
            }
        }
        return out.toString();
    }

    private String sums(final String over) {
        return sums(over, FOUR);
    }

    /** SUM of x squared and of x under a window, per row in i order. */
    private String sums(final String over, final String source) {
        return rows("SELECT i, TO_VARCHAR((SUM(x * x) OVER (" + over + "))::NUMBER(38,20)), TO_VARCHAR((SUM(x) OVER ("
            + over + "))::NUMBER(38,20)) FROM " + source + " ORDER BY i");
    }

    /** AVG of x squared and of x under a window, per row in i order. */
    private String averages(final String over) {
        return rows("SELECT i, TO_VARCHAR((AVG(x * x) OVER (" + over + "))::NUMBER(38,20)), TO_VARCHAR((AVG(x) OVER ("
            + over + "))::NUMBER(38,20)) FROM " + FOUR + " ORDER BY i");
    }

    /** SUM and AVG of one argument under a window, per row in i order. */
    private String both(final String argument, final String over, final String source) {
        return rows("SELECT i, TO_VARCHAR((SUM(" + argument + ") OVER (" + over + "))::NUMBER(38,20)), TO_VARCHAR((AVG("
            + argument + ") OVER (" + over + "))::NUMBER(38,20)) FROM " + source + " ORDER BY i");
    }

    @Test
    public void aMovingFrameReadsItsRunningSum() {
        assertEquals("1, 0.08999999999999999667, 0.29999999999999998890 | 2, 0.57999999999999996003, 1.00000000000000000000 | 3, 0.49999999999999988898, 0.80000000000000004441 | 4, 0.25999999999999995337, 0.60000000000000008882",
            sums("ORDER BY i ROWS BETWEEN 1 PRECEDING AND CURRENT ROW"));
        assertEquals("1, 0.08999999999999999667, 0.29999999999999998890 | 2, 0.48999999999999988010, 0.69999999999999995559 | 3, 0.00999999999999995337, 0.10000000000000008882 | 4, 0.24999999999999994449, 0.50000000000000011102",
            sums("ORDER BY i ROWS BETWEEN CURRENT ROW AND CURRENT ROW"));
        assertEquals("1, 0.57999999999999996003, 0.99999999999999988898 | 2, 0.58999999999999996891, 1.09999999999999986677 | 3, 0.75000000000000000000, 1.29999999999999982236 | 4, 0.26000000000000000888, 0.59999999999999997780",
            sums("ORDER BY i ROWS BETWEEN 1 PRECEDING AND 1 FOLLOWING"));
        assertEquals("1, 0.57999999999999996003, 0.99999999999999988898 | 2, 0.49999999999999994449, 0.79999999999999993339 | 3, 0.26000000000000000888, 0.59999999999999997780 | 4, 0.25000000000000000000, 0.50000000000000000000",
            sums("ORDER BY i ROWS BETWEEN CURRENT ROW AND 1 FOLLOWING"));
        assertEquals("1, null, null | 2, 0.08999999999999999667, 0.29999999999999998890 | 3, 0.57999999999999996003, 1.00000000000000000000 | 4, 0.49999999999999988898, 0.80000000000000004441",
            sums("ORDER BY i ROWS BETWEEN 2 PRECEDING AND 1 PRECEDING"));
        assertEquals("1, 0.57999999999999996003, 0.99999999999999988898 | 2, 0.49999999999999994449, 0.79999999999999993339 | 3, 0.26000000000000000888, 0.59999999999999997780 | 4, 0.25000000000000000000, 0.50000000000000000000",
            sums("ORDER BY i DESC ROWS BETWEEN 1 PRECEDING AND CURRENT ROW"));
        assertEquals("1, 0.83999999999999996891, 1.59999999999999986677 | 2, 0.75000000000000000000, 1.29999999999999982236 | 3, 0.26000000000000000888, 0.59999999999999997780 | 4, 0.25000000000000000000, 0.50000000000000000000",
            sums("ORDER BY i ROWS BETWEEN CURRENT ROW AND UNBOUNDED FOLLOWING"));
        assertEquals("1, 0.08999999999999999667, 0.29999999999999998890 | 2, 0.57999999999999996003, 1.00000000000000000000 | 3, 0.58999999999999985789, 1.10000000000000008882 | 4, 0.83999999999999985789, 1.60000000000000008882",
            sums("ORDER BY i DESC ROWS BETWEEN CURRENT ROW AND UNBOUNDED FOLLOWING"));
        assertEquals("1, null, null | 2, 0.08999999999999999667, 0.29999999999999998890 | 3, 0.57999999999999996003, 1.00000000000000000000 | 4, 0.58999999999999985789, 1.10000000000000008882",
            sums("ORDER BY i ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING"));
        assertEquals("1, 0.26000000000000000888, 0.59999999999999997780 | 2, 0.25000000000000000000, 0.50000000000000000000 | 3, null, null | 4, null, null",
            sums("ORDER BY i ROWS BETWEEN 2 FOLLOWING AND UNBOUNDED FOLLOWING"));
        assertEquals("1, 0.58999999999999996891, 1.09999999999999986677 | 2, 0.83999999999999996891, 1.59999999999999986677 | 3, 0.83999999999999996891, 1.59999999999999986677 | 4, 0.75000000000000000000, 1.29999999999999982236",
            sums("ORDER BY i ROWS BETWEEN 2 PRECEDING AND 2 FOLLOWING"));
        assertEquals("1, 0.08999999999999999667, 0.29999999999999998890 | 2, 0.57999999999999996003, 1.00000000000000000000 | 3, 0.58999999999999985789, 1.10000000000000008882 | 4, 0.83999999999999985789, 1.60000000000000008882",
            sums("ORDER BY i ROWS BETWEEN 3 PRECEDING AND CURRENT ROW"));
    }

    @Test
    public void wideFramesAndNullsFollowTheSameWalk() {
        assertEquals("1, 0.58999999999999996891, 1.09999999999999986677 | 2, 0.83999999999999996891, 1.59999999999999986677 | 3, 1.64999999999999991118, 2.50000000000000000000 | 4, 1.68999999999999994671, 2.69999999999999973355 | 5, 1.60000000000000008882, 2.39999999999999991118 | 6, 1.11000000000000009770, 1.69999999999999995559",
            sums("ORDER BY i ROWS BETWEEN 3 PRECEDING AND 2 FOLLOWING", SIX));
        assertEquals("1, 0.57999999999999996003, 1.00000000000000000000 | 2, 0.58999999999999985789, 1.10000000000000008882 | 3, 0.83999999999999985789, 1.60000000000000008882 | 4, 1.64999999999999991118, 2.50000000000000000000 | 5, 1.68999999999999994671, 2.70000000000000017764 | 6, 1.68999999999999994671, 2.70000000000000017764",
            sums("ORDER BY i ROWS BETWEEN UNBOUNDED PRECEDING AND 1 FOLLOWING", SIX));
        assertEquals("1, 0.75000000000000000000, 1.29999999999999982236 | 2, 1.07000000000000006217, 1.50000000000000000000 | 3, 1.10000000000000008882, 1.60000000000000008882 | 4, 0.85000000000000008882, 1.10000000000000008882 | 5, 0.04000000000000000777, 0.20000000000000001110 | 6, null, null",
            sums("ORDER BY i ROWS BETWEEN 1 FOLLOWING AND 3 FOLLOWING", SIX));
        assertEquals("1, 1.68999999999999994671, 2.69999999999999973355 | 2, 1.68999999999999994671, 2.69999999999999973355 | 3, 1.68999999999999994671, 2.69999999999999973355 | 4, 1.60000000000000008882, 2.39999999999999991118 | 5, 1.11000000000000009770, 1.69999999999999995559 | 6, 1.10000000000000008882, 1.60000000000000008882",
            sums("ORDER BY i ROWS BETWEEN 2 PRECEDING AND UNBOUNDED FOLLOWING", SIX));
        assertEquals("1, 0.58999999999999985789, 1.10000000000000008882 | 2, 0.83999999999999985789, 1.60000000000000008882 | 3, 1.55999999999999983125, 2.20000000000000017764 | 4, 1.10999999999999987566, 1.70000000000000017764 | 5, 1.10000000000000008882, 1.60000000000000008882 | 6, 0.84999999999999997780, 1.10000000000000008882",
            sums("ORDER BY i DESC ROWS BETWEEN 2 PRECEDING AND 1 FOLLOWING", SIX));
        assertEquals("1, 0.57999999999999996003, 0.99999999999999988898 | 2, 0.58999999999999996891, 1.09999999999999986677 | 3, 0.58999999999999996891, 1.09999999999999986677 | 4, 0.83999999999999996891, 1.59999999999999986677 | 5, 0.75000000000000000000, 1.29999999999999982236 | 6, 0.75000000000000000000, 1.29999999999999982236",
            sums("ORDER BY i ROWS BETWEEN 3 PRECEDING AND 2 FOLLOWING", WITH_NULLS));
        assertEquals("1, null, null | 2, 0.08999999999999999667, 0.29999999999999998890 | 3, 0.08999999999999999667, 0.29999999999999998890 | 4, 0.48999999999999988010, 0.69999999999999995559 | 5, 0.49999999999999988898, 0.80000000000000004441 | 6, 0.00999999999999995337, 0.10000000000000008882",
            sums("ORDER BY i ROWS BETWEEN 2 PRECEDING AND 1 PRECEDING", WITH_NULLS));
        assertEquals("1, 0.09000000000000002442, 0.29999999999999993339 | 2, 0.57999999999999996003, 0.99999999999999988898 | 3, 0.49999999999999994449, 0.79999999999999993339 | 4, 0.49999999999999994449, 0.79999999999999993339 | 5, 0.26000000000000000888, 0.59999999999999997780 | 6, 0.25000000000000000000, 0.50000000000000000000",
            sums("ORDER BY i ROWS BETWEEN 1 PRECEDING AND 1 FOLLOWING", WITH_NULLS));
    }

    @Test
    public void aWholePartitionIsSummedInInputOrder() {
        assertEquals("1, 0.83999999999999985789, 1.60000000000000008882 | 2, 0.83999999999999985789, 1.60000000000000008882 | 3, 0.83999999999999985789, 1.60000000000000008882 | 4, 0.83999999999999985789, 1.60000000000000008882",
            sums("ORDER BY i DESC ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING"));
        assertEquals("1, 0.83999999999999985789, 1.60000000000000008882 | 2, 0.83999999999999985789, 1.60000000000000008882 | 3, 0.83999999999999985789, 1.60000000000000008882 | 4, 0.83999999999999985789, 1.60000000000000008882",
            sums("ORDER BY i DESC RANGE BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING"));
        assertEquals("1, 0.83999999999999996891, 1.59999999999999986677 | 2, 0.83999999999999996891, 1.59999999999999986677 | 3, 0.83999999999999996891, 1.59999999999999986677 | 4, 0.83999999999999996891, 1.59999999999999986677",
            sums("ORDER BY i DESC ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING", SCRAMBLED));
        assertEquals("1, 0.83999999999999996891, 1.59999999999999986677 | 2, 0.83999999999999996891, 1.59999999999999986677 | 3, 0.83999999999999996891, 1.59999999999999986677 | 4, 0.83999999999999996891, 1.59999999999999986677",
            sums("ORDER BY i ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING", SCRAMBLED));
        assertEquals("1, 0.83999999999999996891, 1.59999999999999986677 | 2, 0.83999999999999996891, 1.59999999999999986677 | 3, 0.83999999999999996891, 1.59999999999999986677 | 4, 0.83999999999999996891, 1.59999999999999986677",
            sums("", SCRAMBLED));
        assertEquals("1, 0.83999999999999996891, 1.59999999999999986677 | 2, 0.83999999999999996891, 1.59999999999999986677 | 3, 0.83999999999999996891, 1.59999999999999986677 | 4, 0.83999999999999996891, 1.59999999999999986677",
            sums("ORDER BY i RANGE BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING", SCRAMBLED));
        engine.execute("CREATE OR REPLACE TABLE sf (i INT, x FLOAT)");
        engine.execute("INSERT INTO sf VALUES (3, 0.1), (1, 0.3), (4, 0.5), (2, 0.7)");
        assertEquals("1, 0.83999999999999996891, 1.59999999999999986677 | 2, 0.83999999999999996891, 1.59999999999999986677 | 3, 0.83999999999999996891, 1.59999999999999986677 | 4, 0.83999999999999996891, 1.59999999999999986677",
            rows("SELECT i, TO_VARCHAR((SUM(x * x) OVER (ORDER BY i DESC ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED "
                + "FOLLOWING))::NUMBER(38,20)), TO_VARCHAR((SUM(x) OVER (ORDER BY i ROWS BETWEEN UNBOUNDED PRECEDING AND "
                + "UNBOUNDED FOLLOWING))::NUMBER(38,20)) FROM sf ORDER BY i"));
        assertEquals("1, 0.57999999999999996003, 1.59999999999999986677 | 2, 0.49999999999999994449, 1.59999999999999986677 | 3, 0.26000000000000000888, 1.59999999999999986677 | 4, 0.25000000000000000000, 1.59999999999999986677",
            rows("SELECT i, TO_VARCHAR((SUM(x * x) OVER (ORDER BY i ROWS BETWEEN CURRENT ROW AND 1 FOLLOWING))"
                + "::NUMBER(38,20)), TO_VARCHAR((SUM(x) OVER ())::NUMBER(38,20)) FROM sf ORDER BY i"));
    }

    @Test
    public void aMovingAverageAddsPlainly() {
        assertEquals("1, 0.08999999999999999667, 0.29999999999999998890 | 2, 0.28999999999999998002, 0.50000000000000000000 | 3, 0.25000000000000000000, 0.40000000000000002220 | 4, 0.13000000000000003220, 0.30000000000000004441",
            averages("ORDER BY i ROWS BETWEEN 1 PRECEDING AND CURRENT ROW"));
        assertEquals("1, 0.08999999999999999667, 0.29999999999999998890 | 2, 0.48999999999999999112, 0.69999999999999995559 | 3, 0.01000000000000006439, 0.09999999999999997780 | 4, 0.25000000000000005551, 0.50000000000000000000",
            averages("ORDER BY i ROWS BETWEEN CURRENT ROW AND CURRENT ROW"));
        assertEquals("1, 0.28999999999999998002, 0.49999999999999994449 | 2, 0.25000000000000000000, 0.39999999999999991118 | 3, 0.13000000000000000444, 0.29999999999999998890 | 4, 0.25000000000000000000, 0.50000000000000000000",
            averages("ORDER BY i ROWS BETWEEN CURRENT ROW AND 1 FOLLOWING"));
        assertEquals("1, 0.20999999999999996447, 0.40000000000000002220 | 2, 0.20999999999999996447, 0.40000000000000002220 | 3, 0.20999999999999996447, 0.40000000000000002220 | 4, 0.20999999999999996447, 0.40000000000000002220",
            averages("ORDER BY i DESC ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING"));
    }

    @Test
    public void partitionsNullsAndTenthsKeepTheRule() {
        assertEquals("1, 0.08999999999999999667, 0.08999999999999999667 | 2, 0.08999999999999999667, 0.08999999999999999667 | 3, 0.48999999999999988010, 0.48999999999999999112 | 4, 0.49999999999999988898, 0.25000000000000000000 | 5, 0.25000000000000000000, 0.25000000000000000000 | 6, 0.00999999999999995337, 0.01000000000000006439 | 7, 1.06000000000000005329, 0.53000000000000002665",
            both("x * x", "PARTITION BY k ORDER BY i ROWS BETWEEN 1 PRECEDING AND CURRENT ROW", PARTITIONED));
        assertEquals("1, 0.08999999999999996891, 0.09000000000000002442 | 2, 0.48999999999999993561, 0.48999999999999993561 | 3, 0.49999999999999994449, 0.24999999999999997224 | 4, 0.01000000000000000194, 0.01000000000000000194 | 5, 1.06000000000000005329, 0.53000000000000002665 | 6, null, null | 7, 0.81000000000000005329, 0.81000000000000005329",
            both("x * x", "PARTITION BY k ORDER BY i ROWS BETWEEN CURRENT ROW AND 1 FOLLOWING", PARTITIONED));
        assertEquals("1, 0.09000000000000002442, 0.09000000000000002442 | 2, 0.57999999999999996003, 0.28999999999999998002 | 3, 0.49999999999999994449, 0.25000000000000000000 | 4, 0.75000000000000000000, 0.25000000000000000000 | 5, 0.26000000000000000888, 0.13000000000000000444 | 6, 1.06000000000000005329, 0.53000000000000002665 | 7, 0.81000000000000005329, 0.81000000000000005329",
            both("x * x", "ORDER BY i ROWS BETWEEN 1 PRECEDING AND 1 FOLLOWING", PARTITIONED));
        assertEquals("0, 0.10000000000000000555, 0.10000000000000000555 | 1, 0.20000000000000001110, 0.10000000000000000555 | 2, 0.30000000000000004441, 0.10000000000000001943 | 3, 0.40000000000000002220, 0.10000000000000000555 | 4, 0.50000000000000000000, 0.10000000000000000555 | 5, 0.60000000000000008882, 0.09999999999999999167 | 6, 0.70000000000000006661, 0.09999999999999999167 | 7, 0.80000000000000004441, 0.09999999999999999167 | 8, 0.90000000000000002220, 0.09999999999999999167 | 9, 1.00000000000000000000, 0.09999999999999999167 | 10, 1.10000000000000008882, 0.09999999999999999167 | 11, 1.20000000000000017764, 0.09999999999999999167",
            both("x", "ORDER BY i ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW", TENTHS));
        assertEquals("0, 0.10000000000000000555, 0.10000000000000000555 | 1, 0.20000000000000001110, 0.10000000000000000555 | 2, 0.30000000000000004441, 0.10000000000000001943 | 3, 0.30000000000000004441, 0.10000000000000001943 | 4, 0.30000000000000004441, 0.10000000000000001943 | 5, 0.30000000000000004441, 0.10000000000000001943 | 6, 0.30000000000000004441, 0.10000000000000001943 | 7, 0.30000000000000004441, 0.10000000000000001943 | 8, 0.30000000000000004441, 0.10000000000000001943 | 9, 0.30000000000000004441, 0.10000000000000001943 | 10, 0.30000000000000004441, 0.10000000000000001943 | 11, 0.30000000000000004441, 0.10000000000000001943",
            both("x", "ORDER BY i ROWS BETWEEN 2 PRECEDING AND CURRENT ROW", TENTHS));
        assertEquals("0, 0.20000000000000001110, 0.10000000000000000555 | 1, 0.30000000000000004441, 0.10000000000000001943 | 2, 0.40000000000000002220, 0.10000000000000000555 | 3, 0.50000000000000000000, 0.10000000000000000555 | 4, 0.60000000000000008882, 0.09999999999999999167 | 5, 0.70000000000000006661, 0.09999999999999999167 | 6, 0.80000000000000004441, 0.09999999999999999167 | 7, 0.90000000000000002220, 0.09999999999999999167 | 8, 1.00000000000000000000, 0.09999999999999999167 | 9, 1.10000000000000008882, 0.09999999999999999167 | 10, 1.20000000000000017764, 0.09999999999999999167 | 11, 1.20000000000000017764, 0.09999999999999999167",
            both("x", "ORDER BY i ROWS BETWEEN UNBOUNDED PRECEDING AND 1 FOLLOWING", TENTHS));
        assertEquals("0, 1.20000000000000017764, 0.09999999999999999167 | 1, 1.10000000000000008882, 0.09999999999999999167 | 2, 1.00000000000000000000, 0.09999999999999999167 | 3, 0.90000000000000002220, 0.09999999999999999167 | 4, 0.80000000000000004441, 0.09999999999999999167 | 5, 0.70000000000000006661, 0.09999999999999999167 | 6, 0.60000000000000008882, 0.09999999999999999167 | 7, 0.50000000000000000000, 0.10000000000000000555 | 8, 0.40000000000000002220, 0.10000000000000000555 | 9, 0.30000000000000004441, 0.10000000000000001943 | 10, 0.20000000000000001110, 0.10000000000000000555 | 11, 0.10000000000000000555, 0.10000000000000000555",
            both("x", "ORDER BY i ROWS BETWEEN CURRENT ROW AND UNBOUNDED FOLLOWING", TENTHS));
        assertEquals("0, 0.10000000000000000555, 0.10000000000000000555 | 1, 0.20000000000000001110, 0.10000000000000000555 | 2, 0.30000000000000004441, 0.10000000000000001943 | 3, 0.40000000000000002220, 0.10000000000000000555 | 4, 0.40000000000000002220, 0.10000000000000000555 | 5, 0.40000000000000002220, 0.10000000000000000555 | 6, 0.40000000000000002220, 0.10000000000000000555 | 7, 0.40000000000000002220, 0.10000000000000000555 | 8, 0.40000000000000002220, 0.10000000000000000555 | 9, 0.40000000000000002220, 0.10000000000000000555 | 10, 0.40000000000000002220, 0.10000000000000000555 | 11, 0.40000000000000002220, 0.10000000000000000555",
            both("x", "ORDER BY i ROWS 3 PRECEDING", TENTHS));
    }
}
